#include <iostream>
using namespace std;

constexpr long long MOD = 10007;

struct Matrix {
    long long a[3][3]{};
};

Matrix multiply(const Matrix& x, const Matrix& y) {
    Matrix result;
    for (int i = 0; i < 3; ++i)
        for (int k = 0; k < 3; ++k)
            for (int j = 0; j < 3; ++j)
                result.a[i][j] =
                    (result.a[i][j] + x.a[i][k] * y.a[k][j]) % MOD;
    return result;
}

Matrix power(Matrix base, long long exponent) {
    Matrix result;
    for (int i = 0; i < 3; ++i)
        result.a[i][i] = 1;

    while (exponent > 0) {
        if (exponent & 1)
            result = multiply(result, base);
        base = multiply(base, base);
        exponent >>= 1;
    }
    return result;
}

long long f(long long n) {
    if (n < 0) return 0;
    if (n == 0 || n == 1) return 1;
    if (n == 2) return 2;
    if (n == 3) return 4;

    Matrix transition{{
        {1, 1, 1},
        {1, 0, 0},
        {0, 1, 0}
    }};

    Matrix result = power(transition, n - 3);
    return (result.a[0][0] * 4 +
            result.a[0][1] * 2 +
            result.a[0][2]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        long long sum = 1;
        for (int i = 0; i < n - 1; ++i) {
            long long value;
            cin >> value;
            sum = sum * f(value) % MOD;
        }

        cout << sum << '\n';
    }

    return 0;
}

